class Datatable{constructor(){}static buttons(a,t){new $.fn.dataTable.Buttons(this.table,{buttons:[a]}).container().appendTo($(t))}static inputSearch(a,t,n=null){$(t).on("keyup",function(t){"Enter"===t.key&&a.search($(this).val()).draw()}),n&&$(n).on("click",function(){a.search($(t).val()).draw()})}static reloadTable(a){a.ajax.reload()}}export{Datatable};